contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to call c.sendTo with arbitrary inputs and asserts the general rule:
    // - If call reverts then at least one precondition was violated (msg.sender==owner, receiver!=0, amount>0)
    // - If call succeeds then address(c).balance decreases by amount and address(receiver).balance increases by amount
    function run(address payable receiver, uint256 amount) public payable {
        require(true);

        // Ensure this contract has enough balance to cover a transfer attempt if amount is used
        if (address(this).balance < amount) {
            // top up from msg.sender (test harness will provide funds to this call if needed)
            // cannot get funds here; so require that test environment supplies enough value
            return; // if not enough balance, skip (assert must still be meaningful). Early return prevents unreachable assert failure.
        }

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeReceiver = address(receiver).balance;

        // try calling sendTo from this contract (this contract is the owner because InvMutTest deployed c)
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterReceiver = address(receiver).balance;

        // General rule:
        // If call reverted then at least one of: msg.sender != owner (not possible here), receiver == address(0), or amount == 0
        // If call succeeded then c's balance decreased by amount and receiver's balance increased by amount
        // Because this contract deployed c, msg.sender==owner holds; so revert implies receiver==0 || amount==0
        assert(reverted ? (receiver == address(0) || amount == 0) : (beforeC >= afterC && beforeC - afterC == amount && afterReceiver - beforeReceiver == amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to call c.sendTo from this contract (which deployed c, so is owner)
    // Parameters: receiver (any address) and amount (Ether to transfer from c to receiver).
    // This function is payable only so the test harness can fund this contract if needed
    // (we do not rely on msg.value). We require the InvMutTest contract has at least `amount` balance
    // when expecting a successful transfer to be possible; otherwise we still observe contract balance.
    function run(address payable receiver, uint256 amount) public payable {
        require(true);

        // Record c's balance before the call.
        uint256 beforeC = address(c).balance;

        // Attempt the call and record whether it reverted.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record c's balance after the call.
        uint256 afterC = address(c).balance;

        // General rule asserted for all inputs:
        // - If the call reverted, c's balance must be unchanged.
        // - If the call succeeded, c's balance must have decreased by exactly `amount` (i.e. beforeC - afterC == amount).
        // Note: avoid underflow in the assert by branching on reverted.
        assert(reverted ? (afterC == beforeC) : (beforeC >= afterC && beforeC - afterC == amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test calls c.sendTo from this contract (which deployed c and is therefore owner).
    // Preconditions: receiver != address(0), amount > 0, and contract has at least amount balance.
    function run(address payable receiver, uint256 amount) public payable {
        require(receiver != address(0) && amount > 0, "invalid params");
        // Ensure this test contract has enough balance to fund c if needed is not allowed; instead
        // we require the c contract already holds at least `amount`.
        uint256 beforeC = address(c).balance;
        require(beforeC >= amount, "c lacks funds");

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        // If preconditions hold and c had enough balance and caller is owner (this contract is owner),
        // then the call must NOT revert and c's balance must decrease exactly by amount.
        assert(!reverted && beforeC - afterC == amount);
    }

    receive() external payable { }
}

