contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0) && amount > 0);
        // Fund contract c so it can send the requested amount
        require(address(this).balance >= amount);
        // transfer Ether into c so it has balance to forward
        (bool sent,) = payable(address(c)).call{value: amount}("");
        require(sent);

        // record balances before call
        uint beforeC = address(c).balance;
        uint beforeReceiver = address(receiver).balance;

        // try calling sendTo and record whether it reverted
        bool reverted;
        try c.sendTo{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, if it did not revert then: caller must have been owner (which in this setup is the deployer of c, not this test),
        // and balances should reflect the transfer: c balance decreased by amount, receiver increased by >= amount.
        // We assert the general rule: successful call implies balance changes by amount and receiver increases accordingly;
        // unsuccessful call implies at least one precondition (non-owner, zero receiver, or amount > balance) prevented transfer.
        assert(
            reverted
            || (
                address(c).balance + amount == beforeC
                && address(receiver).balance >= beforeReceiver + amount
            )
        );
    }
    receive() external payable { }
}

