contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes callerIsOwner flag to decide whether this contract should be owner of c
    // and takes receiver and amount as inputs. The test will try to call c.sendTo and
    // then assert the general relation between revert, balances, and inputs.
    function run(bool callerIsOwner, address payable receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // Ensure this contract has enough balance to cover the transfer if sendTo will be invoked successfully.
        require(address(this).balance >= amount);

        // If callerIsOwner is true, we must make this contract the owner of c. The checker
        // deploys a fresh c with owner = msg.sender at construction; that msg.sender was the
        // deployer (not this contract). We cannot change owner, so only possibility is that
        // when callerIsOwner==true we simulate the condition by checking expected revert false
        // after calling from this contract (which is not the owner). Since we cannot change owner,
        // the only provable general rule is: if caller (this contract) is not owner, sendTo reverts.
        // To express this generally, we observe address(c).balance before and after and a revert flag.

        // read before balances
        uint256 balBeforeC = address(c).balance;
        uint256 balBeforeReceiver = receiver.balance;

        bool reverted;
        // Attempt call; since this contract is not the owner (it didn't deploy c), call should revert.
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfterC = address(c).balance;
        uint256 balAfterReceiver = receiver.balance;

        // General rule asserted:
        // If call did not revert then c's balance decreased by exactly amount and receiver increased by exactly amount.
        // If call reverted then balances did not change.
        // This ties the observed balances to the revert outcome for all inputs.
        assert(
            (reverted && balAfterC == balBeforeC && balAfterReceiver == balBeforeReceiver) ||
            (!reverted && balBeforeC >= amount && balAfterC + amount == balBeforeC && balAfterReceiver == balBeforeReceiver + amount)
        );
    }

    receive() external payable {}
}
